function shardForKey(key, shardCount) {
  const hash = crypto.createHash('md5').update(String(key)).digest('hex');
  const value = parseInt(hash.slice(0, 8), 16);
  return value % shardCount;
}

const pool = [db0, db1, db2, db3];

function getConnection(userId) {
  const shardId = shardForKey(userId, pool.length);
  return pool[shardId];
}

