public int shardForKey(String key, int shardCount) {
    int hash = Math.abs(key.hashCode());
    return hash % shardCount;
}

public Connection getConnection(String userId) {
    int shardId = shardForKey(userId, pool.size());
    return pool.get(shardId);
}
